<div class="page-head"><div><h1>Oportunidades</h1><p>Turnos disponíveis que combinam com o seu perfil.</p></div></div><div class="filter-row panel"><div class="top-search inline-search"><?=icon('search',17)?><input placeholder="Função, empresa ou cidade"></div><select><option>Até 10 km</option><option>Até 25 km</option><option>Até 50 km</option></select><select><option>Próximos 7 dias</option><option>Hoje</option><option>Amanhã</option></select></div><section class="panel"><div class="opportunity-list big"><?php foreach($opportunities as $s):?><div class="opportunity-row"><div class="venue-thumb"><?=e(mb_substr($s['category_name'],0,1))?></div><div class="opp-role"><strong><?=e($s['category_name'])?></strong><span><?=e($s['company_name'])?> · ★ <?=number_format((float)$s['company_rating'],1,',','.')?></span><small><?=icon('map',13)?> <?=e($s['city'].' – '.$s['state'])?></small></div><div class="opp-meta"><?=icon('calendar',16)?><div><strong><?=br_date($s['starts_at'],'d/m')?></strong><small><?=date('D',strtotime($s['starts_at']))?></small></div></div><div class="opp-meta"><?=icon('clock',16)?><div><strong><?=date('H:i',strtotime($s['starts_at']))?> – <?=date('H:i',strtotime($s['ends_at']))?></strong></div></div><div class="opp-value"><strong><?=money($s['shift_value'])?></strong><small>por turno</small></div><div class="opp-distance"><?=icon('map',17)?><div><strong><?=number_format(1.5+($s['id']%6)*.6,1,',','.')?> km</strong><small>da sua localização</small></div></div><div class="opp-actions"><a class="btn btn-soft" href="<?=e(url('profissional/vagas/'.$s['id']))?>">Ver detalhes</a><form method="post" action="<?=e(url('profissional/vagas/'.$s['id'].'/aceitar'))?>"><?=csrf_field()?><button class="btn btn-primary">Aceitar</button></form></div></div><?php endforeach;?></div></section>
